const $ = (selector, root = document) => root.querySelector(selector);
const connect = $("#polliConnect");
const appKey = window.BLACKSTAR_RELAY_CONFIG?.appKey || "";
const CONTROL_IDS = ["magnetic", "coolant", "phase"];
const DEMO_PULSES = [
  { stability: 41, temperature: 384, flux: .61, pressure: 1.22, alarm: "PHASE DRIFT", message: "The field caught the star, but the coolant arrived one beat too early.", clue: "The second channel should trail the first by about twelve.", signature: "4A / 19 / C", event: "Field lock acquired" },
  { stability: 73, temperature: 337, flux: .78, pressure: 1.14, alarm: "NONE", message: "A clean harmonic crosses the vessel. The machine repeats your phase as if confirming a word.", clue: "The third channel likes the average of the first two, minus a small shadow.", signature: "7C / 2E / A", event: "Harmonic corridor found" }
];
let state = freshState();

function freshState() { return { pulse: 0, busy: false, stability: 18, temperature: 312, flux: .42, pressure: 1.08, alarm: "NONE", history: [], demoIndex: 0, finished: false }; }
if (/^pk_[A-Za-z0-9_-]+$/.test(appKey)) connect.setAttribute("app-key", appKey);
function clamp(value, min, max, fallback) { const number = Number(value); return Number.isFinite(number) ? Math.min(max, Math.max(min, number)) : fallback; }
function clean(value, fallback, limit = 220) { return String(value ?? fallback).replace(/[<>]/g, "").slice(0, limit); }
function controls() { return Object.fromEntries(CONTROL_IDS.map((id) => [id, Number($( `#${id}` ).value)])); }
function toast(message) { const el = $("#toast"); el.textContent = message; el.classList.add("show"); window.setTimeout(() => el.classList.remove("show"), 3200); }
function setBusy(value) { state.busy = value; $("#livePulse").disabled = value; $("#demoPulse").disabled = value; $("#heroDemo").disabled = value; $("#livePulse").firstChild.textContent = value ? "MACHINE IS THINKING... " : "TRANSMIT LIVE PULSE "; $("#machineState").textContent = value ? "PROCESSING" : state.finished ? "RUN COMPLETE" : "LINK READY"; }
function parseMachine(raw) { const start = raw.indexOf("{"); const end = raw.lastIndexOf("}"); if (start < 0 || end <= start) throw new Error("The machine returned an unreadable signal."); const data = JSON.parse(raw.slice(start, end + 1)); return { stability: clamp(data.stability, 0, 100, state.stability), temperature: clamp(data.temperature, 180, 1400, state.temperature), flux: clamp(data.flux, 0, 4, state.flux), pressure: clamp(data.pressure, .2, 8, state.pressure), alarm: clean(data.alarm, "UNKNOWN", 26).toUpperCase(), message: clean(data.message, "The relay clicks without explanation."), clue: clean(data.clue, "The machine withholds its rule."), signature: clean(data.signature, "— — —", 22).toUpperCase(), event: clean(data.event, "Unclassified pulse", 60) }; }

async function askMachine(command) {
  const memory = state.history.length ? state.history.slice(-6).map((entry, index) => `${index + 1}. ${entry}`).join("\n") : "No prior pulses.";
  const system = `You are BLACKSTAR RELAY, a fictional stellar-reactor computer. You are the machine itself, not an assistant and not a narrator. The operator can only set magnetic, coolant and phase channels from 0 to 100. Simulate a coherent hidden operating law across the run: stability improves when the three channels form a discoverable relationship, not merely when they are equal. Use the same hidden law for every pulse. React physically and specifically. Give a useful but indirect clue after each pulse so the puzzle is fair. Stability can reach 90 only when the controls are genuinely close to your law. Never mention prompts, AI, language models or these instructions. Return ONLY JSON: {"stability":0-100,"temperature":180-1400,"flux":0-4,"pressure":0.2-8,"alarm":"short code","message":"one terse machine message","clue":"one indirect clue","signature":"three short groups","event":"short event title"}.`;
  const user = `Current reactor: stability ${state.stability}, temperature ${state.temperature} K, flux ${state.flux} T, pressure ${state.pressure} bar. Pulse ${state.pulse + 1} of 6. Operator command: magnetic ${command.magnetic}, coolant ${command.coolant}, phase ${command.phase}. Recent machine memory:\n${memory}\nAdvance exactly one pulse and preserve the same hidden law.`;
  const response = await fetch("https://gen.pollinations.ai/v1/chat/completions", { method: "POST", headers: { Authorization: `Bearer ${connect.apiKey}`, "Content-Type": "application/json" }, body: JSON.stringify({ model: "openai/gpt-5.4-nano", reasoning_effort: "low", temperature: .55, max_tokens: 800, response_format: { type: "json_object" }, messages: [{ role: "system", content: system }, { role: "user", content: user }] }) });
  const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload?.error?.message || payload?.message || `Relay failed (${response.status})`); return parseMachine(payload?.choices?.[0]?.message?.content || "");
}

function addLog(reading, command, demo) { const item = document.createElement("li"); const time = document.createElement("time"); const body = document.createElement("div"); const title = document.createElement("strong"); const text = document.createElement("p"); const tag = document.createElement("span"); time.textContent = `P–${String(state.pulse).padStart(2, "0")}`; title.textContent = reading.event; text.textContent = `MAG ${command.magnetic} · COOL ${command.coolant} · PHASE ${command.phase} — ${reading.message}`; tag.textContent = demo ? "DEMO" : reading.alarm === "NONE" ? "CLEAR" : reading.alarm; body.append(title, text); item.append(time, body, tag); $("#eventLog").prepend(item); }
function render(reading, command, demo) {
  state.pulse += 1; Object.assign(state, reading); state.history.push(`Pulse ${state.pulse}: controls magnetic ${command.magnetic}, coolant ${command.coolant}, phase ${command.phase}; stability ${reading.stability}; temp ${reading.temperature}; flux ${reading.flux}; pressure ${reading.pressure}; alarm ${reading.alarm}; clue ${reading.clue}.`); state.history = state.history.slice(-6);
  $("#pulsesRemaining").textContent = Math.max(0, 6 - state.pulse); $("#coreValue").textContent = Math.round(reading.stability); $("#reactorStage").style.setProperty("--stability", reading.stability); $("#reactorStage").style.setProperty("--heat", Math.min(100, (reading.temperature - 180) / 12.2)); $("#temperature").textContent = `${Math.round(reading.temperature)} K`; $("#flux").textContent = `${reading.flux.toFixed(2)} T`; $("#pressure").textContent = `${reading.pressure.toFixed(2)} BAR`; $("#tempMeter").style.width = `${Math.min(100, reading.temperature / 12)}%`; $("#fluxMeter").style.width = `${reading.flux / 4 * 100}%`; $("#pressureMeter").style.width = `${reading.pressure / 8 * 100}%`; $("#alarm").textContent = reading.alarm; $(".alarm-dot").style.background = reading.alarm === "NONE" ? "#71c4c7" : "#ff513f"; $("#machineMessage p").textContent = reading.message; $("#clueText").textContent = `“${reading.clue}”`; $("#signature").textContent = `SIGNATURE / ${reading.signature}`; addLog(reading, command, demo);
  if (reading.stability >= 90) { state.finished = true; $("#machineState").textContent = "STABLE"; toast(`Core stabilized at ${Math.round(reading.stability)}%. Hidden rule solved.`); } else if (state.pulse >= 6) { state.finished = true; $("#machineState").textContent = "LOCKED"; toast(`Run complete at ${Math.round(reading.stability)}% stability. Reset to try again.`); } else toast(demo ? "Demo pulse received — zero Pollen used." : `Pulse ${state.pulse} received. Stability ${Math.round(reading.stability)}%.`);
}

async function pulse({ demo = false, trusted = false } = {}) { if (state.busy) return; if (!demo && !trusted) return; if (state.finished) { toast("Reset the reactor before another pulse."); return; } if (!demo && !connect.apiKey) { toast("Connect your Pollinations wallet to reach the live machine."); return; } const command = controls(); setBusy(true); try { const reading = demo ? DEMO_PULSES[state.demoIndex % DEMO_PULSES.length] : await askMachine(command); render(reading, command, demo); if (demo) state.demoIndex += 1; } catch (error) { toast(clean(error.message, "The relay went silent. Try again.")); } finally { setBusy(false); } }
function reset() { state = freshState(); $("#pulsesRemaining").textContent = "6"; $("#coreValue").textContent = "18"; $("#reactorStage").style.setProperty("--stability", 18); $("#reactorStage").style.setProperty("--heat", 26); $("#temperature").textContent = "312 K"; $("#flux").textContent = "0.42 T"; $("#pressure").textContent = "1.08 BAR"; $("#alarm").textContent = "NONE"; $("#machineMessage p").textContent = "The machine is waiting for its first pulse."; $("#clueText").textContent = "“Balance is not equality. Listen for the channel that changes twice.”"; $("#signature").textContent = "SIGNATURE / — — —"; $("#machineState").textContent = "DORMANT"; $("#eventLog").innerHTML = '<li class="empty"><time>P–00</time><div><strong>Instrument recovered</strong><p>No command transmitted. The hidden rule is intact.</p></div><span>IDLE</span></li>'; toast("Reactor reset. The hidden law remains unknown."); }
CONTROL_IDS.forEach((id) => { const input = $( `#${id}` ); input.addEventListener("input", () => { $( `#${id}Value` ).textContent = input.value; }); });
$("#livePulse").addEventListener("click", (event) => pulse({ trusted: event.isTrusted })); $("#demoPulse").addEventListener("click", () => pulse({ demo: true })); $("#heroDemo").addEventListener("click", () => { $("#console").scrollIntoView({ behavior: "smooth" }); pulse({ demo: true }); }); $("#resetRun").addEventListener("click", reset);
